```python
import sys

def fast_pow(x, y, p):
    return pow(x, y, p)

def init(maxi, p, fac, inv):
    fac[0] = 1
    for i in range(1, maxi + 1):
        fac[i] = fac[i-1] * i % p
    inv[maxi] = pow(fac[maxi], p-2, p)
    for i in range(maxi - 1, -1, -1):
        inv[i] = inv[i+1] * (i+1) % p

def lower(x):
    tmp = 1
    while tmp < x:
        tmp <<= 1
    return tmp

def FWT(now, len_, p, t_ref, type_=False):
    # t_ref is the temporary array of length len_ (list of ints)
    T = t_ref
    for i in range(len_):
        T[i] = now[i]
    if type_:
        # inverse
        i = 1
        while i < len_:
            for j in range(0, len_, i << 1):
                for k in range(j, j + i):
                    T[i + k] -= T[k]
            i <<= 1
    else:
        i = 1
        while i < len_:
            for j in range(0, len_, i << 1):
                for k in range(j, j + i):
                    T[i + k] += T[k]
            i <<= 1
    for i in range(len_):
        now[i] = T[i] % p
        if now[i] < 0:
            now[i] += p

def __a(x, pp):
    if x >= pp:
        x -= pp
    return x

def multi(f, ct, maxi, p, pp, tmp1, tmp2, tmp3, t, long_t):
    # long_t is a list of 20 lists (each of length maxi+1)
    for j in range(20):
        for s in range(maxi + 1):
            tmp1[j][s] = 0
        for s in range(maxi + 1):
            long_t[j][s] = 0
    for j in range(maxi + 1):
        tmp1[ct[j]][j] = f[j]
    for j in range(20):
        FWT(tmp1[j], maxi + 1, p, t[j], False)  # use t[j] as temporary for FWT
    for q in range(20):
        for l in range(20 - q):
            for s in range(maxi + 1):
                long_t[q+l][s] = __a(long_t[q+l][s] + tmp1[q][s] * tmp2[l][s], pp)
    for q in range(20):
        for s in range(maxi + 1):
            tmp3[q][s] = long_t[q][s] % p
    for j in range(20):
        FWT(tmp3[j], maxi + 1, p, t[j], True)
    for j in range(maxi + 1):
        f[j] = tmp3[ct[j]][j]

def multi2(ct, maxi, p, pp, tmp2, t, long_t):
    tmp = [[0] * (maxi + 1) for _ in range(20)]
    for i in range(20):
        for s in range(maxi + 1):
            long_t[i][s] = 0
    for q in range(20):
        for l in range(20 - q):
            for s in range(maxi + 1):
                long_t[q+l][s] = __a(long_t[q+l][s] + tmp2[q][s] * tmp2[l][s], pp)
    for q in range(20):
        for s in range(maxi + 1):
            tmp[q][s] = long_t[q][s] % p
    for i in range(20):
        FWT(tmp[i], maxi + 1, p, t[i], True)
    for i in range(20):
        for s in range(maxi + 1):
            tmp2[i][s] = 0
    for i in range(maxi + 1):
        tmp2[ct[i]][i] = tmp[ct[i]][i]
    for i in range(20):
        FWT(tmp2[i], maxi + 1, p, t[i], False)

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    p = int(data[2])
    pp = p * p

    if n & 1:
        print(fast_pow(k, n, p))
        return

    maxi = lower(n + 1) - 1
    max_len = maxi + 1

    fac = [0] * (max_len)
    inv = [0] * (max_len)
    init(maxi, p, fac, inv)

    f = [0] * max_len
    f[0] = 1

    ct = [0] * max_len
    for i in range(max_len):
        ct[i] = i.bit_count()

    # allocate 2D arrays
    tmp1 = [[0] * max_len for _ in range(20)]
    tmp2 = [[0] * max_len for _ in range(20)]
    tmp3 = [[0] * max_len for _ in range(20)]
    t = [[0] * max_len for _ in range(20)]  # temporary for FWT (one row per layer? actually we need separate temps for each layer to avoid interference)
    long_t = [[0] * max_len for _ in range(20)]  # for accumulation

    # initialize tmp2
    for i in range(max_len):
        tmp2[ct[i]][i] = inv[i]
    for i in range(20):
        FWT(tmp2[i], max_len, p, t[i], False)  # each layer gets its own temporary row

    res_k = k
    while k:
        sys.stderr.write(str(k) + '\n')
        if k & 1:
            multi(f, ct, maxi, p, pp, tmp1, tmp2, tmp3, t, long_t)
        k >>= 1
        if k:
            multi2(ct, maxi, p, pp, tmp2, t, long_t)

    ans = (fast_pow(res_k, n, p) - fac[n] * f[n] % p + p) % p
    print(ans)

if __name__ == "__main__":
    main()
